'use strict';
let selectedMapItem=null;
function mapItem(ref){if(!ref)return null;if(ref.kind==='trap'){const box=state.traps.find(t=>t.id===ref.id);return box?{ref,box,locked:true,label:'Bear Trap '+ref.id}:null}if(ref.kind==='member'){const m=state.members.find(m=>m.id===ref.id),box=slotBy(m?.slot);return box?{ref,box,locked:!!m.locked,label:m.name}:null}const list=ref.kind==='slot'?state.slots:ref.kind==='terrain'?state.blocks:state.structures,box=list.find(o=>o.id===ref.id);return box?{ref,box,locked:false,label:ref.kind==='slot'?'+ City':ref.kind==='terrain'?'Terrain':box.kind==='hq'?'Alliance HQ':box.kind==='node'?'Resource node':'Banner'}:null}
function hitDraggable(p){const inside=b=>visible(b)&&p.x>=b.x&&p.x<b.x+b.w&&p.y>=b.y&&p.y<b.y+b.h;const slot=state.slots.find(inside);if(slot){const m=memberAt(slot.id);return mapItem({kind:m?'member':'slot',id:m?m.id:slot.id})}const b=state.blocks.find(inside);if(b)return mapItem({kind:'terrain',id:b.id});const o=state.structures.find(inside);if(o)return mapItem({kind:'object',id:o.id});const t=state.traps.find(t=>visible({...t,trap:t.id})&&p.x>=t.x&&p.x<t.x+t.w&&p.y>=t.y&&p.y<t.y+t.h);return t?mapItem({kind:'trap',id:t.id}):null}
function canDragItem(ref,x,y){try{Hive.moveMapItem(state,ref,x,y);return true}catch{return false}}
function applyDragItem(ref,x,y){try{const item=mapItem(ref);if(item.box.x===x&&item.box.y===y)return;const next=Hive.moveMapItem(state,ref,x,y);commit(()=>state=next);selectedMapItem=ref;setTool('select');renderMap();toast('Position updated. Undo is available.')}catch(e){toast(e.message)}}
function removeSelectedMapItem(){const item=mapItem(selectedMapItem);if(!item||readonly)return;try{const ref=item.ref,target=ref.kind==='member'?{memberId:ref.id}:ref.kind==='slot'?{slotId:ref.id}:ref.kind==='terrain'?{terrainId:ref.id}:{objectId:ref.id};const next=Hive.removeMapObject(state,target);commit(()=>state=next);selectedMapItem=null;renderMap();toast(ref.kind==='member'?'City removed. Player kept in the queue. Undo is available.':'Item removed. Undo is available.')}catch(e){toast(e.message)}}
const directBaseTap=mapTap;mapTap=function(e,target){if(target.closest('[data-map-action]'))return;if(!readonly&&isPlacementTool(tool)){const r=viewport.getBoundingClientRect(),p=screenWorld(e.clientX-r.left,e.clientY-r.top),d=Hive.mapPlacementPreview(state,tool,Math.floor(p.x),Math.floor(p.y),activeTrap==='all'?+state.operations.rosterGroup:+activeTrap);applyPlacement(d);return}if(readonly||tool!=='select'){directBaseTap(e,target);if(!readonly&&tool==='assign'){setTool('select');renderMap()}return}const r=viewport.getBoundingClientRect(),hit=hitDraggable(screenWorld(e.clientX-r.left,e.clientY-r.top));if(hit){selectedMapItem=hit.ref;selectedSlot=hit.ref.kind==='slot'?hit.ref.id:hit.ref.kind==='member'?state.members.find(m=>m.id===hit.ref.id).slot:null;if(hit.ref.kind==='slot')state.operations.rosterGroup=hit.box.trap;renderMap();renderQueue();return}selectedMapItem=null;selectedSlot=null;selectedMember=null;renderMap();renderQueue();directBaseTap(e,target)};
function finishMapEditing(){
 cancelMapGesture();selectedMapItem=null;selectedSlot=null;selectedMember=null;setTool('select');renderMap();renderQueue();
}
const directBaseMap=renderMap;
renderMap=function(){
 directBaseMap();const actions=$('#mapItemActions'),item=mapItem(selectedMapItem);
 if(item){const outline=document.createElementNS('http://www.w3.org/2000/svg','polygon');outline.setAttribute('points',polygon(item.box));outline.setAttribute('fill','none');outline.setAttribute('stroke','#397151');outline.setAttribute('stroke-width','3');outline.setAttribute('pointer-events','none');outline.setAttribute('data-selection-outline','true');$('#mapSvg').appendChild(outline)}
 actions.classList.toggle('gesture-hidden',!!item&&!!mapPointers.size);
 if(!item||readonly||mapPointers.size||isPlacementTool(tool)){actions.hidden=true;return}
 actions.hidden=false;
 const renderKey=JSON.stringify({ref:item.ref,box:item.box,label:item.label,locked:item.locked});
 if(actions.dataset.renderKey===renderKey)return;actions.dataset.renderKey=renderKey;
 const fixedTrap=item.ref.kind==='trap';
 actions.innerHTML=`<div class="selection-heading"><span>${esc(item.label)}${item.locked&&!fixedTrap?' · 🔒 Locked':''}<small class="selected-coordinates">X:${Hive.coord(state,item.box).x} Y:${Hive.coord(state,item.box).y}</small></span><button class="primary selection-done" data-map-action="done">✓ Done</button></div><div class="selection-buttons">${item.ref.kind==='slot'?'':'<button data-map-action="details">Details</button>'}${item.ref.kind==='member'&&item.locked?'<button data-map-action="unlock">Unlock</button>':''}${!fixedTrap?`<button data-map-action="coordinates" ${item.locked?'disabled':''}>Coordinates</button><button data-map-action="remove" aria-label="Remove ${esc(item.label)} from map" ${item.locked?'disabled':''}>− Remove</button>`:''}</div>`;
 actions.querySelector('[data-map-action="done"]').onclick=finishMapEditing;
 const remove=actions.querySelector('[data-map-action="remove"]');if(remove)remove.onclick=removeSelectedMapItem;
 const details=actions.querySelector('[data-map-action="details"]');if(details)details.onclick=()=>{if(item.ref.kind==='member')memberDetail(item.ref.id);else if(fixedTrap)trapDetails(item.ref.id);else objectModal(item.box,item.ref.kind==='terrain')};
 const unlock=actions.querySelector('[data-map-action="unlock"]');if(unlock)unlock.onclick=()=>{commit(()=>{state.members.find(m=>m.id===item.ref.id).locked=false});toast('City unlocked. Undo is available.')};
 const coords=actions.querySelector('[data-map-action="coordinates"]');if(coords)coords.onclick=()=>openSelectedCoordinates(item.ref);
};
function openSelectedCoordinates(ref){const item=mapItem(ref);if(!item||item.locked)return;const c=Hive.coord(state,item.box);openModal(`<h2>Move ${esc(item.label)}</h2><form id="moveItemCoordinates"><div class="two"><label>X<input name="x" type="number" min="0" max="1199" step="1" required value="${c.x}" inputmode="numeric"></label><label>Y<input name="y" type="number" min="0" max="1199" step="1" required value="${c.y}" inputmode="numeric"></label></div><button class="primary">Move item</button></form>`);$('#moveItemCoordinates').onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(e.target)),o=Hive.worldOrigin(state),next=Hive.moveMapItem(state,ref,+v.x-o.x,+v.y-o.y);commit(()=>state=next);closeModal();toast('Position updated. Undo is available.')}catch(e){toast(e.message)}}}
function openAttendanceSlot(id){const slot=slotBy(id);if(!slot)return;openModal(`<div class="eyebrow">ASSIGN A PLAYER · BT${slot.trap}</div><h2>Choose player</h2><p>${esc(slotLabel(id))}</p><label>Search players<input id="slotSearch" type="search" placeholder="Username or player ID" autocomplete="off"></label><p id="slotAttendanceGroup" role="status"></p><div id="slotSuggestions" class="sheet-list"></div>`);const show=()=>{const group=Hive.slotAttendanceGroup(state,slot.trap,{query:$('#slotSearch').value});$('#slotAttendanceGroup').textContent=group.remaining?group.label+' · '+group.groupCount+' unassigned':'All players for this trap are assigned.';$('#slotSuggestions').innerHTML=group.members.map(m=>`<button data-slot-candidate="${esc(m.id)}"><strong>${esc(m.name)}</strong><small>${esc(frequencyBadge(m,slot.trap))}</small></button>`).join('')||(group.remaining?'<p>No matches in this attendance group.</p>':'');$$('[data-slot-candidate]').forEach(b=>b.onclick=()=>{try{const next=Hive.assignAvailableSlotMember(state,id,b.dataset.slotCandidate);commit(()=>state=next);selectedMapItem={kind:'member',id:b.dataset.slotCandidate};closeModal();renderMap();toast('Player assigned. Undo is available.')}catch(e){toast(e.message)}})};$('#slotSearch').oninput=show;show()}
// A placement tool stays active until tapped again or cancelled with Escape.
const directBaseTool=setTool;setTool=function(t){directBaseTool(t);$$('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===t)));$('#mapHint').textContent=placementHint()};
function togglePlacementTool(t){cancelMapGesture();selectedMapItem=null;setTool(tool===t?'select':t);renderMap()}
$$('[data-tool]').forEach(b=>b.onclick=()=>togglePlacementTool(b.dataset.tool));
window.addEventListener('keydown',e=>{if(e.key==='Escape')finishMapEditing()});
function isPlacementTool(t){return ['slot','block','flag','hq','water','node','farm','mine','wood','coal','iron'].includes(t)}
function placementHint(){return isPlacementTool(tool)?'Hold and position · Release to place · ✓ Done to finish':gestureHint}
function updatePlacement(){if(!mapPlacement)return;const p=screenWorld(mapPlacement.screen.x,mapPlacement.screen.y);Object.assign(mapPlacement,Hive.mapPlacementPreview(state,mapPlacement.tool,Math.floor(p.x),Math.floor(p.y),activeTrap==='all'?+state.operations.rosterGroup:+activeTrap));renderMap()}
function applyPlacement(d){try{const preview=Hive.mapPlacementPreview(state,d.tool,d.x,d.y,d.trap);if(!preview.valid)throw Error(preview.error);const origin=Hive.worldOrigin(state),next=Hive.placeMapObject(state,preview.kind,origin.x+d.x,origin.y+d.y,{trapId:preview.trap});commit(()=>state=next);toast('Placed. Keep adding or tap ✓ Done.')}catch(e){toast(e.message)}renderMap()}
// Inline controls replace the phone-only modal panels.
closeMapSheets();$('#toggleQueue').hidden=true;$('#toggleTools').hidden=true;$('#closeQueueSheet').hidden=true;$('#closeToolsSheet').hidden=true;
setTool(tool);renderMap();
